silver_df = silver_df.sort_values('datetime_minute').reset_index(drop=True)

# Classify power state
def classify(power):
    if power <= -2000:
        return 'charging'
    elif power >= 2000:
        return 'discharging'
    else:
        return 'idle'

silver_df['state'] = silver_df['RTAC_P'].apply(classify)
